import { NextResponse } from "next/server";
import { ZodError } from "zod";
import { Prisma } from "@/generated/prisma/client";
import type { ErrorCode } from "@/schema/error";

export type { ErrorCode } from "@/schema/error";

export class AppError extends Error {
  constructor(
    public code: ErrorCode,
    message: string,
    public context?: Record<string, unknown>,
  ) {
    super(message);
    this.name = "AppError";
  }
}

export const errorStatusMap: Record<ErrorCode, number> = {
  VALIDATION_ERROR: 400,
  NOT_FOUND: 404,
  UNAUTHORIZED: 401,
  FORBIDDEN: 403,
  DATABASE_ERROR: 500,
  EMAIL_ERROR: 500,
  INTERNAL_ERROR: 500,
  RATE_LIMITED: 429,
  GROUP_NOT_FOUND: 404,
  GROUP_ACCESS_DENIED: 403,
  MEMBER_ALREADY_IN_GROUP: 400,
  MEMBER_NOT_IN_GROUP: 404,
  INVALID_MEMBER_ID: 400,
  SMS_CONSENT_REQUIRED: 403,
  MESSAGE_SEND_FAILED: 500,
  BLAST_NOT_AUTHORIZED: 403,
};

export function transformError(error: unknown): AppError {
  if (error instanceof AppError) {
    return error;
  }

  if (error instanceof ZodError) {
    const messages = error.issues.map((issue) => `${issue.path.join(".")}: ${issue.message}`);
    return new AppError("VALIDATION_ERROR", messages.join(", "), {
      issues: error.issues,
    });
  }

  if (error instanceof Prisma.PrismaClientKnownRequestError) {
    if (error.code === "P2025") {
      return new AppError("NOT_FOUND", "Record not found", {
        prismaCode: error.code,
      });
    }
    return new AppError("DATABASE_ERROR", "Database operation failed", {
      prismaCode: error.code,
    });
  }

  if (error instanceof Prisma.PrismaClientValidationError) {
    return new AppError("VALIDATION_ERROR", "Invalid data provided");
  }

  if (error instanceof Error) {
    return new AppError("INTERNAL_ERROR", error.message);
  }

  if (typeof error === "string") {
    return new AppError("INTERNAL_ERROR", error);
  }

  return new AppError("INTERNAL_ERROR", "An unexpected error occurred");
}

export function apiErrorHandler(error: unknown): NextResponse {
  const appError = transformError(error);

  console.error(`[${appError.code}] ${appError.message}`, appError.context);

  return NextResponse.json(
    { error: { code: appError.code, message: appError.message } },
    { status: errorStatusMap[appError.code] },
  );
}

/**
 * @jest-environment node
 */
import { AppError, transformError, apiErrorHandler } from "@/utils/errors";
import { z } from "zod";

describe("AppError", () => {
  it("stores code, message, and context", () => {
    const err = new AppError("DATABASE_ERROR", "Query failed", {
      table: "referral",
    });

    expect(err.code).toBe("DATABASE_ERROR");
    expect(err.message).toBe("Query failed");
    expect(err.context).toEqual({ table: "referral" });
  });
});

describe("transformError", () => {
  it("passes through AppError unchanged", () => {
    const original = new AppError("NOT_FOUND", "Missing");
    expect(transformError(original)).toBe(original);
  });

  it("converts ZodError to VALIDATION_ERROR", () => {
    const schema = z.object({ email: z.email() });
    let caught: unknown;
    try {
      schema.parse({ email: "bad" });
    } catch (e) {
      caught = e;
    }

    const result = transformError(caught);

    expect(result.code).toBe("VALIDATION_ERROR");
  });

  it("wraps unknown errors as INTERNAL_ERROR", () => {
    const result = transformError({ unexpected: true });

    expect(result.code).toBe("INTERNAL_ERROR");
  });
});

describe("apiErrorHandler", () => {
  const cases: Array<[string, number]> = [
    ["VALIDATION_ERROR", 400],
    ["NOT_FOUND", 404],
    ["UNAUTHORIZED", 401],
    ["DATABASE_ERROR", 500],
  ];

  it.each(cases)("%s maps to HTTP %i", (code, status) => {
    const err = new AppError(code as "VALIDATION_ERROR" | "NOT_FOUND" | "UNAUTHORIZED" | "DATABASE_ERROR", "msg");
    const res = apiErrorHandler(err);

    expect(res.status).toBe(status);
  });
});

