"use client";

import { useState, useEffect, useMemo, useCallback } from "react";
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  flexRender,
  type ColumnDef,
  type SortingState,
  type ColumnFiltersState,
  type VisibilityState,
} from "@tanstack/react-table";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { cn } from "@/lib/utils";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import type { ApiReferral } from "@/schema/api";
import { operatorFilter, type FilterOperator, type ColumnFilterValue } from "./table-filters";
import { toast } from "sonner";
import { useReferrals } from "@/hooks/use-referrals";
import { useIsMobile } from "@/hooks/use-mobile";

import { Skeleton } from "@/components/ui/skeleton";
import { DataTableToolbar } from "./data-table-toolbar";
import { DataTableFilterPanel } from "./data-table-filter-panel";
import { DataTablePagination } from "./data-table-pagination";
import { DataTableMobileDrawer } from "./data-table-mobile-drawer";
import { type Density, densityClasses } from "./data-table-types";

const STORAGE_KEY = "referral-table-columns";

export function ReferralDataGrid() {
  const { data: referrals, error, isLoading, isFetching, toggleRedeemed } = useReferrals();
  const isMobile = useIsMobile();
  const [sorting, setSorting] = useState<SortingState>([{ id: "createdAt", desc: true }]);
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
  // null = CSS handles responsive visibility, object = user overrides
  const [userOverrides, setUserOverrides] = useState<VisibilityState | null>(null);
  const [rowSelection, setRowSelection] = useState({});
  const [globalFilter, setGlobalFilter] = useState("");
  const [density, setDensity] = useState<Density>("standard");

  const [showFilterPanel, setShowFilterPanel] = useState(false);
  const [filterColumn, setFilterColumn] = useState("createdAt");
  const [filterOperator, setFilterOperator] = useState<FilterOperator>("contains");
  const [filterValue, setFilterValue] = useState("");
  const [columnSearch, setColumnSearch] = useState("");
  const [mobileDrawerOpen, setMobileDrawerOpen] = useState(false);

  useEffect(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        setUserOverrides(JSON.parse(stored));
      }
    } catch {
      // localStorage unavailable or corrupted
    }
  }, []);

  const hasCustomized = userOverrides !== null;

  const handleColumnVisibilityChange = useCallback(
    (updater: VisibilityState | ((prev: VisibilityState) => VisibilityState)) => {
      setUserOverrides((prev) => {
        const next = typeof updater === "function" ? updater(prev ?? {}) : updater;
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
        } catch {
          // localStorage full or unavailable
        }
        return next;
      });
    },
    [],
  );

  const resetColumnVisibility = useCallback(() => {
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch {
      // localStorage unavailable
    }
    setUserOverrides(null);
  }, []);

  useEffect(() => {
    if (error) {
      toast.error("Failed to load referrals");
    }
  }, [error]);

  useEffect(() => {
    if (isMobile && showFilterPanel) {
      setShowFilterPanel(false);
    }
  }, [isMobile, showFilterPanel]);

  const formatDate = useCallback((date: string | Date) => {
    return new Intl.DateTimeFormat("en-US", {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hour12: true,
    }).format(new Date(date));
  }, []);

  const columns: ColumnDef<ApiReferral>[] = useMemo(
    () => [
      {
        id: "select",
        header: ({ table }) => (
          <Checkbox
            checked={table.getIsAllPageRowsSelected() || (table.getIsSomePageRowsSelected() && "indeterminate")}
            onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
            aria-label="Select all rows"
          />
        ),
        cell: ({ row }) => (
          <Checkbox
            checked={row.getIsSelected()}
            onCheckedChange={(value) => row.toggleSelected(!!value)}
            aria-label="Select row"
          />
        ),
        enableSorting: false,
        enableHiding: false,
      },
      {
        accessorKey: "createdAt",
        header: "Date",
        cell: ({ row }) => formatDate(row.getValue("createdAt")),
        filterFn: operatorFilter,
        meta: { className: "hidden md:table-cell", responsiveHidden: "md" },
      },
      {
        accessorKey: "memberName",
        header: "Member Name",
        enableHiding: false,
        filterFn: operatorFilter,
      },
      {
        accessorKey: "memberEmail",
        header: "Member Email",
        filterFn: operatorFilter,
        meta: { className: "hidden lg:table-cell", responsiveHidden: "lg" },
      },
      {
        accessorKey: "prospectName",
        header: "Prospect Name",
        enableHiding: false,
        filterFn: operatorFilter,
      },
      {
        accessorKey: "prospectEmail",
        header: "Prospect Email",
        filterFn: operatorFilter,
        meta: { className: "hidden lg:table-cell", responsiveHidden: "lg" },
      },
      {
        accessorKey: "referralCode",
        header: "Code",
        filterFn: operatorFilter,
        meta: { className: "hidden md:table-cell", responsiveHidden: "md" },
      },
      {
        accessorKey: "redeemed",
        header: () => <div className="text-center">Redeemed</div>,
        enableHiding: false,
        cell: ({ row }) => (
          <div className="flex justify-center">
            <Switch
              checked={row.getValue("redeemed")}
              onCheckedChange={() => toggleRedeemed(row.original.id, row.getValue("redeemed"))}
              aria-label="Toggle redeemed status"
            />
          </div>
        ),
      },
    ],
    [formatDate, toggleRedeemed],
  );

  const placeholderRows = useMemo(() => Array(10).fill({} as ApiReferral), []);
  const skeletonColumns: ColumnDef<ApiReferral>[] = useMemo(
    () => columns.map((column) => ({ ...column, cell: () => <Skeleton className="h-4 w-full" /> })),
    [columns],
  );

  const tableRows = isLoading ? placeholderRows : referrals;
  const tableCols = isLoading ? skeletonColumns : columns;

  const table = useReactTable({
    data: tableRows,
    columns: tableCols,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onColumnVisibilityChange: handleColumnVisibilityChange,
    onRowSelectionChange: setRowSelection,
    onGlobalFilterChange: setGlobalFilter,
    globalFilterFn: "includesString",
    state: {
      sorting,
      columnFilters,
      columnVisibility: userOverrides ?? {},
      rowSelection,
      globalFilter,
    },
  });

  const handleClearFilter = useCallback(() => {
    setFilterValue("");
    setColumnFilters([]);
    setShowFilterPanel(false);
  }, []);

  const hiddenColumnCount = table
    .getAllColumns()
    .filter((column) => column.getCanHide() && !column.getIsVisible()).length;
  const isFiltered = columnFilters.length > 0;

  const exportToPDF = useCallback(() => {
    const doc = new jsPDF();
    const tableColumns = ["Date", "Member Name", "Member Email", "Prospect Name", "Prospect Email", "Code", "Redeemed"];
    const tableRows = table
      .getFilteredRowModel()
      .rows.map((row) => [
        formatDate(row.original.createdAt),
        row.original.memberName,
        row.original.memberEmail,
        row.original.prospectName,
        row.original.prospectEmail,
        row.original.referralCode,
        row.original.redeemed ? "Yes" : "No",
      ]);

    doc.setFontSize(16);
    doc.text("Paso Food Co-op Referral Database", doc.internal.pageSize.getWidth() / 2, 15, { align: "center" });

    autoTable(doc, {
      head: [tableColumns],
      body: tableRows,
      startY: 25,
      styles: { fontSize: 10 },
      headStyles: { fillColor: [131, 16, 2] },
      alternateRowStyles: { fillColor: [237, 221, 204] },
      margin: { left: 10, right: 10 },
    });

    doc.autoPrint();
    window.open(doc.output("bloburl"), "_blank");
  }, [table, formatDate]);

  const handleFilterValueChange = useCallback(
    (value: string) => {
      setFilterValue(value);
      if (value.trim()) {
        setColumnFilters([
          {
            id: filterColumn,
            value: { text: value, operator: filterOperator } as ColumnFilterValue,
          },
        ]);
      } else {
        setColumnFilters([]);
      }
    },
    [filterColumn, filterOperator],
  );

  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-col gap-2 p-2 md:flex-row md:items-center md:justify-between">
        <div className="flex items-center gap-2">
          <div
            className="flex flex-1 items-center bg-white px-2 py-1"
            style={{
              border: "2px solid #831002",
              borderRadius: "28px",
            }}
          >
            <svg
              className="w-5 h-5 text-gray-500 mr-1"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
              aria-hidden="true"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"
              />
            </svg>
            <Input
              type="text"
              placeholder="Search…"
              value={globalFilter}
              onChange={(event) => setGlobalFilter(event.target.value)}
              className="border-none shadow-none focus-visible:ring-0 w-40 p-0 h-auto text-sm"
              aria-label="Search referrals"
            />
          </div>

          <DataTableMobileDrawer
            table={table}
            open={mobileDrawerOpen}
            onOpenChange={setMobileDrawerOpen}
            density={density}
            onDensityChange={setDensity}
            filterColumn={filterColumn}
            filterOperator={filterOperator}
            filterValue={filterValue}
            onFilterColumnChange={setFilterColumn}
            onFilterOperatorChange={setFilterOperator}
            onFilterValueChange={handleFilterValueChange}
            onClearFilter={handleClearFilter}
            onResetColumns={resetColumnVisibility}
            isFiltered={isFiltered}
            hiddenColumnCount={hiddenColumnCount}
          />
        </div>

        <DataTableToolbar
          table={table}
          density={density}
          onDensityChange={setDensity}
          onToggleFilterPanel={() => setShowFilterPanel(!showFilterPanel)}
          columnSearch={columnSearch}
          onColumnSearchChange={setColumnSearch}
          onResetColumns={resetColumnVisibility}
          hasCustomized={hasCustomized}
        />

        <Button
          onClick={exportToPDF}
          className="w-full md:w-auto text-white border-none rounded cursor-pointer"
          style={{
            backgroundColor: "#831002",
            padding: "8px 16px",
          }}
        >
          Export to PDF
        </Button>
      </div>

      <div
        role="region"
        aria-label="Referral data table"
        aria-busy={isFetching ? "true" : "false"}
        tabIndex={0}
        className={cn(
          "overflow-x-auto focus:outline-2 focus:outline-blue-500 transition-opacity",
          isFetching && !isLoading && "opacity-60",
        )}
        style={{
          border: "2px solid #968676",
          borderRadius: "12px",
        }}
      >
        <DataTableFilterPanel
          visible={showFilterPanel}
          filterColumn={filterColumn}
          filterOperator={filterOperator}
          filterValue={filterValue}
          onColumnChange={setFilterColumn}
          onOperatorChange={setFilterOperator}
          onValueChange={handleFilterValueChange}
          onClear={handleClearFilter}
        />
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow
                key={headerGroup.id}
                style={{
                  borderTop: "2px solid #968676",
                  backgroundColor: "#EDDDCC",
                }}
              >
                {headerGroup.headers.map((header) => (
                  <TableHead
                    key={header.id}
                    className={cn(
                      "font-bold",
                      header.column.getCanSort() && "cursor-pointer underline select-none",
                      !hasCustomized && header.column.columnDef.meta?.className,
                    )}
                    style={{ color: "#831002" }}
                    onClick={header.column.getToggleSortingHandler()}
                  >
                    {header.isPlaceholder ? null : flexRender(header.column.columnDef.header, header.getContext())}
                    {{
                      asc: " ↑",
                      desc: " ↓",
                    }[header.column.getIsSorted() as string] ?? null}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows?.length ? (
              table.getRowModel().rows.map((row, index) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() && "selected"}
                  className={cn(densityClasses[density])}
                  style={{
                    backgroundColor: index % 2 === 0 ? "#ffffff" : "#D9D9D9",
                    transition: "none",
                  }}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell
                      key={cell.id}
                      className={!hasCustomized ? cell.column.columnDef.meta?.className : undefined}
                    >
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={tableCols.length} className="h-24 text-center">
                  {isLoading ? "" : "No referrals found"}
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>

      <DataTablePagination table={table} />
    </div>
  );
}

export default ReferralDataGrid;

"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { z } from "zod";
import { ApiReferralSchema, type ApiReferral } from "@/schema/api";
import { toggleRedeemed as toggleRedeemedAction } from "@/actions/referral";

interface UseReferralsReturn {
  data: ApiReferral[];
  error: Error | null;
  isLoading: boolean;
  isFetching: boolean;
  refetch: () => Promise<void>;
  toggleRedeemed: (id: number, currentValue: boolean) => Promise<void>;
}

export function useReferrals(): UseReferralsReturn {
  const [data, setData] = useState<ApiReferral[]>([]);
  const [error, setError] = useState<Error | null>(null);
  const [isFetching, setIsFetching] = useState(true);
  const hasFetched = useRef(false);

  const isLoading = isFetching && !hasFetched.current;

  const fetchReferrals = useCallback(async () => {
    setIsFetching(true);
    setError(null);
    try {
      const response = await fetch("/api/referral");
      if (!response.ok) {
        throw new Error(`Failed to fetch referrals: ${response.status}`);
      }
      const json = await response.json();
      const validated = z.array(ApiReferralSchema).parse(json);
      setData(validated);
      hasFetched.current = true;
    } catch (caughtError) {
      const error = caughtError instanceof Error ? caughtError : new Error("Unknown error");
      setError(error);
      console.error("[useReferrals] Fetch error:", error);
    } finally {
      setIsFetching(false);
    }
  }, []);

  useEffect(() => {
    fetchReferrals();
  }, [fetchReferrals]);

  const toggleRedeemed = useCallback(async (id: number, currentValue: boolean) => {
    setData((prev) =>
      prev.map((referral) => (referral.id === id ? { ...referral, redeemed: !currentValue } : referral)),
    );

    const result = await toggleRedeemedAction(id);

    if (!result.success) {
      setData((prev) =>
        prev.map((referral) => (referral.id === id ? { ...referral, redeemed: currentValue } : referral)),
      );
      console.error("[useReferrals] Toggle error:", result.error);
    }
  }, []);

  return {
    data,
    error,
    isLoading,
    isFetching,
    refetch: fetchReferrals,
    toggleRedeemed,
  };
}

import { z } from "zod";
import { ReferralSchema, ProspectSchema } from "./referral";

export const ReferralFormSchema = z.object({
  memberName: z.string().min(1).max(255),
  memberEmail: z.string().max(255).pipe(z.email()),
  referralCode: z.string().min(1).max(100),
  prospects: z.array(ProspectSchema).min(1).max(5),
});

export const ChecksumSchema = z.object({
  memberName: z.string().min(1).max(255),
  memberEmail: z.string().max(255).pipe(z.email()),
  referralCode: z.string().min(1).max(100),
  checksum: z.string().min(1),
});

export const UpdateRedeemedSchema = z.object({
  redeemed: z.boolean(),
});

export const ApiReferralSchema = ReferralSchema.extend({
  createdAt: z.coerce.date(),
});

export type ReferralForm = z.infer<typeof ReferralFormSchema>;
export type ChecksumInput = z.infer<typeof ChecksumSchema>;
export type UpdateRedeemed = z.infer<typeof UpdateRedeemedSchema>;
export type ApiReferral = z.infer<typeof ApiReferralSchema>;

import type { Row, FilterFn } from "@tanstack/react-table";
import type { ApiReferral } from "@/schema/api";

export type FilterOperator =
  | "contains"
  | "doesNotContain"
  | "equals"
  | "doesNotEqual"
  | "startsWith"
  | "endsWith"
  | "isEmpty"
  | "isNotEmpty";

export interface ColumnFilterValue {
  text: string;
  operator: FilterOperator;
}

const filterOperations: Record<FilterOperator, (cellValue: string, filterText: string) => boolean> = {
  contains: (cellValue, filterText) => cellValue.includes(filterText),
  doesNotContain: (cellValue, filterText) => !cellValue.includes(filterText),
  equals: (cellValue, filterText) => cellValue === filterText,
  doesNotEqual: (cellValue, filterText) => cellValue !== filterText,
  startsWith: (cellValue, filterText) => cellValue.startsWith(filterText),
  endsWith: (cellValue, filterText) => cellValue.endsWith(filterText),
  isEmpty: (cellValue) => cellValue === "",
  isNotEmpty: (cellValue) => cellValue !== "",
};

export const operatorFilter: FilterFn<ApiReferral> = (
  row: Row<ApiReferral>,
  columnId: string,
  filterValue: ColumnFilterValue,
): boolean => {
  const cell = String(row.getValue(columnId) ?? "").toLowerCase();
  const text = filterValue.text.toLowerCase();
  return filterOperations[filterValue.operator](cell, text);
};

operatorFilter.autoRemove = (value: ColumnFilterValue) => !value?.text || value.text.trim() === "";

export const filterOperators: { value: FilterOperator; label: string }[] = [
  { value: "contains", label: "contains" },
  { value: "doesNotContain", label: "does not contain" },
  { value: "equals", label: "equals" },
  { value: "doesNotEqual", label: "does not equal" },
  { value: "startsWith", label: "starts with" },
  { value: "endsWith", label: "ends with" },
  { value: "isEmpty", label: "is empty" },
  { value: "isNotEmpty", label: "is not empty" },
];

