import { NextRequest, NextResponse } from "next/server";
import { verifyUnsubscribeToken } from "@/lib/unsubscribe-tokens";
import prisma from "@/lib/db";
import { transformError, errorStatusMap } from "@/utils/errors";

export async function POST(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const token = searchParams.get("token");

    if (!token) {
      return NextResponse.json({ error: "Token required" }, { status: 400 });
    }

    const verification = verifyUnsubscribeToken(token);

    if (!verification.valid) {
      return NextResponse.json({ error: verification.error }, { status: 400 });
    }

    const { memberId, groupId } = verification;

    await prisma.contactGroupMember.updateMany({
      where: {
        memberId: memberId!,
        groupId: groupId!,
      },
      data: {
        notifyEmail: false,
        unsubscribedAt: new Date(),
        unsubscribeMethod: "one-click",
      },
    });

    return new NextResponse(null, { status: 204 });
  } catch (error) {
    const appError = transformError(error);
    const status = errorStatusMap[appError.code] || 500;
    console.error("[UNSUBSCRIBE_ERROR]", appError.message, appError.context);
    return NextResponse.json({ error: appError.message }, { status });
  }
}

import "server-only";
import crypto from "crypto";
import { env } from "@/env";

export interface UnsubscribeTokenPayload {
  memberId: number;
  groupId: number;
  timestamp: number;
}

export interface TokenVerificationResult {
  valid: boolean;
  error?: string;
  memberId?: number;
  groupId?: number;
  timestamp?: number;
}

const TEN_YEARS_MS = 10 * 365 * 24 * 60 * 60 * 1000;

export function generateUnsubscribeToken(memberId: number, groupId: number): string {
  const timestamp = Date.now();
  const payload = `${memberId}|${groupId}|${timestamp}`;

  const signature = crypto.createHmac("sha256", env.UNSUBSCRIBE_SECRET).update(payload).digest("base64url");

  const token = Buffer.from(`${payload}|${signature}`).toString("base64url");
  return token;
}

export function verifyUnsubscribeToken(token: string): TokenVerificationResult {
  try {
    const decoded = Buffer.from(token, "base64url").toString("utf-8");
    const parts = decoded.split("|");

    if (parts.length !== 4) {
      return { valid: false, error: "Invalid token format" };
    }

    const [memberIdStr, groupIdStr, timestampStr, signature] = parts;

    const expectedSignature = crypto
      .createHmac("sha256", env.UNSUBSCRIBE_SECRET)
      .update(`${memberIdStr}|${groupIdStr}|${timestampStr}`)
      .digest("base64url");

    if (!crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSignature))) {
      return { valid: false, error: "Invalid signature" };
    }

    const memberId = parseInt(memberIdStr, 10);
    const groupId = parseInt(groupIdStr, 10);
    const timestamp = parseInt(timestampStr, 10);

    if (Number.isNaN(memberId) || Number.isNaN(groupId) || Number.isNaN(timestamp)) {
      return { valid: false, error: "Invalid token format" };
    }

    const tokenAge = Date.now() - timestamp;

    if (tokenAge > TEN_YEARS_MS) {
      return { valid: false, error: "Token expired" };
    }

    return {
      valid: true,
      memberId,
      groupId,
      timestamp,
    };
  } catch {
    return { valid: false, error: "Token parsing failed" };
  }
}

