    });
  } catch (error) {
    throw transformError(error);
  }
}

export async function createManyReferrals(referrals: CreateReferral[]) {
  try {
    const validatedReferrals = referrals.map((data) => CreateReferralSchema.parse(data));

    return await prisma.$transaction(
      validatedReferrals.map((data) =>
        prisma.referral.create({
          data: {
            memberName: data.memberName,
            memberEmail: data.memberEmail,
            prospectName: data.prospectName,
            prospectEmail: data.prospectEmail,
            referralCode: data.referralCode,
            redeemed: data.redeemed ?? false,
          },
        }),
      ),
    );
  } catch (error) {
    throw transformError(error);
  }
}

export async function toggleReferralRedeemed(id: number) {
  try {
    const existing = await prisma.referral.findUnique({ where: { id } });

    if (!existing) {
      throw new AppError("NOT_FOUND", `Referral with id ${id} not found`);
    }

    return await prisma.referral.update({
      where: { id },
      data: { redeemed: !existing.redeemed },
    });
  } catch (error) {
    throw transformError(error);
  }
}

export async function updateReferralRedeemed(id: number, redeemed: boolean) {
  try {
    return await prisma.referral.update({
      where: { id },
      data: { redeemed },
    });
  } catch (error) {
    throw transformError(error);
  }
}

import { z } from "zod";

export const ReferralSchema = z.object({
  id: z.number().int().positive(),
  createdAt: z.coerce.date(),
  updatedAt: z.coerce.date(),
  memberName: z.string().min(1).max(255),
  memberEmail: z.string().max(255).pipe(z.email()),
  prospectName: z.string().min(1).max(255),
  prospectEmail: z.string().max(255).pipe(z.email()),
  referralCode: z.string().min(1).max(100),
  redeemed: z.boolean(),
});

export const CreateReferralSchema = ReferralSchema.omit({
  id: true,
  createdAt: true,
  updatedAt: true,
}).extend({
  redeemed: z.boolean().default(false),
});

export const ProspectSchema = z.object({
  prospectName: z.string().min(1).max(255),
  prospectEmail: z.string().max(255).pipe(z.email()),
});

export type Referral = z.infer<typeof ReferralSchema>;
export type CreateReferral = z.infer<typeof CreateReferralSchema>;
export type Prospect = z.infer<typeof ProspectSchema>;

