  }

  let body;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON" }, { status: 400 });
  }

  const ownerid = parseInt(body.ownerid, 10);
  const isAdmin = Boolean(body.isAdmin);

