  const isAdmin = Boolean(body.isAdmin);

  if (isNaN(ownerid)) {
    return NextResponse.json({ error: "Invalid ownerid" }, { status: 400 });
  }

  const token = generateToken(ownerid, isAdmin);

  return NextResponse.json({ token });
