import "server-only";
import { cache } from "react";
import { cookies } from "next/headers";
import { createHmac, timingSafeEqual } from "crypto";
import { AppError } from "@/utils/errors";

export const AUTH_COOKIE = "prfc_auth";
const TOKEN_EXPIRY_MS = 3600000;
const DEV_SECRET = "dev-only-prfc-connect-hmac-secret-32ch";

export function getSecret(): string {
  const secret = process.env.PRFC_PORTAL_SECRET;
  if (secret) return secret;

  if (process.env.NODE_ENV === "production") {
    throw new AppError("INTERNAL_ERROR", "PRFC_PORTAL_SECRET required in production");
  }

  return DEV_SECRET;
}

export interface Session {
  ownerid: number;
  isAdmin: boolean;
}

function verifyHmac(payload: string, signature: string, secret: string): boolean {
  if (signature.length !== 8) return false;

  const expected = createHmac("sha256", secret).update(payload).digest("hex").slice(0, 8);

  return timingSafeEqual(Buffer.from(signature, "utf8"), Buffer.from(expected, "utf8"));
}

export function validateToken(token: string, secret: string): Session | null {
  const parts = token.split("|");
  if (parts.length !== 4) return null;

  const [ownerid, isAdmin, timestamp, signature] = parts;
  if (!ownerid || !isAdmin || !timestamp || !signature) return null;

  const payload = `${ownerid}|${isAdmin}|${timestamp}`;
  if (!verifyHmac(payload, signature, secret)) return null;

  const tokenTime = parseInt(timestamp, 10);
  if (isNaN(tokenTime) || Date.now() - tokenTime > TOKEN_EXPIRY_MS) return null;

  const parsedOwnerId = parseInt(ownerid, 10);
  if (isNaN(parsedOwnerId)) return null;

  return {
    ownerid: parsedOwnerId,
    isAdmin: isAdmin === "1",
  };
}

export const verifySession = cache(async (): Promise<Session> => {
  const cookieStore = await cookies();
  const authCookie = cookieStore.get(AUTH_COOKIE);

  if (!authCookie?.value) {
    throw new AppError("UNAUTHORIZED", "Authentication required");
  }

  const session = validateToken(authCookie.value, getSecret());
  if (!session) {
    throw new AppError("UNAUTHORIZED", "Invalid or expired token");
  }

  return session;
});

export const getSession = cache(async (): Promise<Session | null> => {
  const cookieStore = await cookies();
  const authCookie = cookieStore.get(AUTH_COOKIE);

  if (!authCookie?.value) {
    return null;
  }

  return validateToken(authCookie.value, getSecret());
});

export async function requireAdmin(): Promise<Session> {
  const session = await verifySession();
  if (!session.isAdmin) {
    throw new AppError("FORBIDDEN", "Admin access required");
  }
  return session;
}

export function generateToken(ownerid: number, isAdmin: boolean): string {
  const timestamp = Date.now().toString();
  const payload = `${ownerid}|${isAdmin ? "1" : "0"}|${timestamp}`;
  const signature = createHmac("sha256", getSecret()).update(payload).digest("hex").slice(0, 8);
  return `${payload}|${signature}`;
}

import "server-only";
import { PrismaClient } from "@/generated/prisma/client";
import { PrismaMariaDb } from "@prisma/adapter-mariadb";
import { PrismaTiDBCloud } from "@tidbcloud/prisma-adapter";
import { env } from "@/env";

function createAdapter() {
  // TiDB serverless uses HTTPS, avoiding connection pool exhaustion in Vercel
  if (process.env.VERCEL) {
    return new PrismaTiDBCloud({ url: env.DATABASE_URL });
  }

  // Local/CI uses TCP connection to Docker MySQL
  const url = new URL(env.DATABASE_URL);
  return new PrismaMariaDb({
    host: url.hostname,
    port: url.port ? parseInt(url.port, 10) : 3306,
    user: url.username,
    password: url.password,
    database: url.pathname.slice(1),
    connectionLimit: 5,
    keepAliveDelay: 30000,
    socketTimeout: 60000,
  });
}

const globalForPrisma = globalThis as unknown as {
  prisma: PrismaClient | undefined;
};

export const prisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    adapter: createAdapter(),
    log: env.NODE_ENV === "development" ? ["query", "error", "warn"] : ["error"],
  });

if (env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;

export default prisma;

import { NextRequest, NextResponse } from "next/server";
import { ReferralFormSchema } from "@/schema/api";
import { createManyReferrals, getAllReferrals } from "@/services/referral";
import { sendReferralEmails } from "@/services/email";
import { rateLimiter } from "@/lib/rate-limit";
import { getIdempotentResponse, setIdempotentResponse } from "@/lib/idempotency";
import { validateOrigin } from "@/lib/csrf";
import { requireAdmin } from "@/lib/dal";
import { transformError, errorStatusMap } from "@/utils/errors";

export async function POST(req: NextRequest) {
  if (!validateOrigin(req)) {
    return NextResponse.json({ error: { code: "FORBIDDEN", message: "Invalid origin" } }, { status: 403 });
  }

  const idempotencyKey = req.headers.get("idempotency-key");

  try {
    if (idempotencyKey) {
      const cached = await getIdempotentResponse(idempotencyKey);
      if (cached) {
        return NextResponse.json(cached.body, { status: cached.status });
      }
    }

    if (rateLimiter) {
      const forwarded = req.headers.get("x-forwarded-for");
      const ip = forwarded?.split(",")[0]?.trim() ?? "127.0.0.1";
      const { success, remaining, reset } = await rateLimiter.limit(ip);

      if (!success) {
        return NextResponse.json(
          { error: { code: "RATE_LIMITED", message: "Too many requests" } },
          {
            status: 429,
            headers: {
              "X-RateLimit-Remaining": remaining.toString(),
              "X-RateLimit-Reset": reset.toString(),
            },
          },
        );
      }
    }

    const body = await req.json();
    const { memberName, memberEmail, referralCode, prospects } = ReferralFormSchema.parse(body);

    await sendReferralEmails({ prospects, referralCode, memberName });

    const referrals = prospects.map((prospect) => ({
      memberName,
      memberEmail,
      prospectName: prospect.prospectName,
      prospectEmail: prospect.prospectEmail,
      referralCode,
      redeemed: false,
    }));

    const newReferrals = await createManyReferrals(referrals);

    const responseBody = { message: "Referrals created successfully!", referrals: newReferrals };

    if (idempotencyKey) {
      await setIdempotentResponse(idempotencyKey, 201, responseBody);
    }

    return NextResponse.json(responseBody, { status: 201 });
  } catch (error) {
    const appError = transformError(error);
    const status = errorStatusMap[appError.code];
    const errorBody = { error: { code: appError.code, message: appError.message } };

    console.error(`[${appError.code}] ${appError.message}`, appError.context);

    if (idempotencyKey) {
      await setIdempotentResponse(idempotencyKey, status, errorBody);
    }

    return NextResponse.json(errorBody, { status });
  }
}

export async function GET() {
  try {
    await requireAdmin();
    const referrals = await getAllReferrals();
    return NextResponse.json(referrals, { status: 200 });
  } catch (error) {
    const appError = transformError(error);
    const status = errorStatusMap[appError.code];
    console.error(`[${appError.code}] ${appError.message}`, appError.context);
    return NextResponse.json({ error: { code: appError.code, message: appError.message } }, { status });
  }
}

